done = 0
for rel, pairs in EDITS:
    p = ROOT / rel
    if not p.exists():
        print(f"FAIL: {rel} is missing. Run passes 1-52 first.")
        sys.exit(1)
    t = p.read_text()
    if all(new in t for _, new in pairs):
        print(f"  already   {rel}")
        done += 1
        continue
    for old, new in pairs:
        if t.count(old) != 1:
            print(f"FAIL: {rel}  anchor found {t.count(old)} times, expected 1.")
            print("      Run passes 1-52 first. Stopping without changes.")
            sys.exit(1)
    if not CHECK:
        for old, new in pairs:
            t = t.replace(old, new, 1)
        p.write_text(t)
    print(f"  {'would patch' if CHECK else 'patched  '} {rel}  ({len(pairs)} hunk(s))")

if done == len(EDITS):
    print("  nothing to do - pass 53 is already applied")
